25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * MAC control receive
33	 */
34	module mac_ctrl_rx #
35	(
36	    parameter DATA_WIDTH = 8,
37	    parameter KEEP_ENABLE = DATA_WIDTH>8,
38	    parameter KEEP_WIDTH = DATA_WIDTH/8,
39	    parameter ID_ENABLE = 0,
40	    parameter ID_WIDTH = 8,
41	    parameter DEST_ENABLE = 0,
42	    parameter DEST_WIDTH = 8,
43	    parameter USER_ENABLE = 1,
44	    parameter USER_WIDTH = 1,
45	    parameter USE_READY = 0,
46	    parameter MCF_PARAMS_SIZE = 18
47	)
48	(
49	    input  wire                          clk,
50	    input  wire                          rst,
51	
52	    /*
53	     * AXI stream input
54	     */
55	    input  wire [DATA_WIDTH-1:0]         s_axis_tdata,
56	    input  wire [KEEP_WIDTH-1:0]         s_axis_tkeep,
57	    input  wire                          s_axis_tvalid,
58	    output wire                          s_axis_tready,
59	    input  wire                          s_axis_tlast,
60	    input  wire [ID_WIDTH-1:0]           s_axis_tid,
61	    input  wire [DEST_WIDTH-1:0]         s_axis_tdest,
62	    input  wire [USER_WIDTH-1:0]         s_axis_tuser,
63	
64	    /*
65	     * AXI stream output
66	     */
67	    output wire [DATA_WIDTH-1:0]         m_axis_tdata,
68	    output wire [KEEP_WIDTH-1:0]         m_axis_tkeep,
69	    output wire                          m_axis_tvalid,
70	    input  wire                          m_axis_tready,
71	    output wire                          m_axis_tlast,
72	    output wire [ID_WIDTH-1:0]           m_axis_tid,
73	    output wire [DEST_WIDTH-1:0]         m_axis_tdest,
74	    output wire [USER_WIDTH-1:0]         m_axis_tuser,
75	
76	    /*
77	     * MAC control frame interface
78	     */
79	    output wire                          mcf_valid,
80	    output wire [47:0]                   mcf_eth_dst,
81	    output wire [47:0]                   mcf_eth_src,
82	    output wire [15:0]                   mcf_eth_type,
83	    output wire [15:0]                   mcf_opcode,
84	    output wire [MCF_PARAMS_SIZE*8-1:0]  mcf_params,
85	    output wire [ID_WIDTH-1:0]           mcf_id,
86	    output wire [DEST_WIDTH-1:0]         mcf_dest,
87	    output wire [USER_WIDTH-1:0]         mcf_user,
88	
89	    /*
90	     * Configuration
91	     */
92	    input  wire [47:0]                   cfg_mcf_rx_eth_dst_mcast,
93	    input  wire                          cfg_mcf_rx_check_eth_dst_mcast,
94	    input  wire [47:0]                   cfg_mcf_rx_eth_dst_ucast,
95	    input  wire                          cfg_mcf_rx_check_eth_dst_ucast,
96	    input  wire [47:0]                   cfg_mcf_rx_eth_src,
97	    input  wire                          cfg_mcf_rx_check_eth_src,
98	    input  wire [15:0]                   cfg_mcf_rx_eth_type,
99	    input  wire [15:0]                   cfg_mcf_rx_opcode_lfc,
100	    input  wire                          cfg_mcf_rx_check_opcode_lfc,
101	    input  wire [15:0]                   cfg_mcf_rx_opcode_pfc,
102	    input  wire                          cfg_mcf_rx_check_opcode_pfc,
103	    input  wire                          cfg_mcf_rx_forward,
104	    input  wire                          cfg_mcf_rx_enable,
105	
106	    /*
107	     * Status
108	     */
109	    output wire                          stat_rx_mcf
110	);
111	
112	parameter BYTE_LANES = KEEP_ENABLE ? KEEP_WIDTH : 1;
113	
114	parameter HDR_SIZE = 60;
115	
116	parameter CYCLE_COUNT = (HDR_SIZE+BYTE_LANES-1)/BYTE_LANES;
117	
118	parameter PTR_WIDTH = $clog2(CYCLE_COUNT);
119	
120	parameter OFFSET = HDR_SIZE % BYTE_LANES;
121	
122	// check configuration
123	initial begin
124	    if (BYTE_LANES * 8 != DATA_WIDTH) begin
125	        $error("Error: AXI stream interface requires byte (8-bit) granularity (instance %m)");
126	        $finish;
127	    end
128	
129	    if (MCF_PARAMS_SIZE > 44) begin
130	        $error("Error: Maximum MCF_PARAMS_SIZE is 44 bytes (instance %m)");
131	        $finish;
132	    end
133	end
134	
135	/*
136	
137	MAC control frame
138	
139	 Field                       Length
140	 Destination MAC address     6 octets [01:80:C2:00:00:01]
141	 Source MAC address          6 octets
142	 Ethertype                   2 octets [0x8808]
143	 Opcode                      2 octets
144	 Parameters                  0-44 octets
145	
146	This module manages the reception of MAC control frames.  Incoming frames are
147	checked based on the ethertype and (optionally) MAC addresses.  Matching control
148	frames are marked by setting tuser[0] on the data output and forwarded through
149	a separate interface for processing.
150	
151	*/
152	
153	reg read_mcf_reg = 1'b1, read_mcf_next;
154	reg mcf_frame_reg = 1'b0, mcf_frame_next;
155	reg [PTR_WIDTH-1:0] ptr_reg = 0, ptr_next;
156	
157	reg s_axis_tready_reg = 1'b0, s_axis_tready_next;
158	
159	// internal datapath
160	reg  [DATA_WIDTH-1:0] m_axis_tdata_int;
161	reg  [KEEP_WIDTH-1:0] m_axis_tkeep_int;
162	reg                   m_axis_tvalid_int;
163	reg                   m_axis_tready_int_reg = 1'b0;
164	reg                   m_axis_tlast_int;
165	reg  [ID_WIDTH-1:0]   m_axis_tid_int;
166	reg  [DEST_WIDTH-1:0] m_axis_tdest_int;
167	reg  [USER_WIDTH-1:0] m_axis_tuser_int;
168	wire                  m_axis_tready_int_early;
169	
170	reg                          mcf_valid_reg = 0, mcf_valid_next;
171	reg [47:0]                   mcf_eth_dst_reg = 0, mcf_eth_dst_next;
172	reg [47:0]                   mcf_eth_src_reg = 0, mcf_eth_src_next;
173	reg [15:0]                   mcf_eth_type_reg = 0, mcf_eth_type_next;
174	reg [15:0]                   mcf_opcode_reg = 0, mcf_opcode_next;
175	reg [MCF_PARAMS_SIZE*8-1:0]  mcf_params_reg = 0, mcf_params_next;
176	reg [ID_WIDTH-1:0]           mcf_id_reg = 0, mcf_id_next;
177	reg [DEST_WIDTH-1:0]         mcf_dest_reg = 0, mcf_dest_next;
178	reg [USER_WIDTH-1:0]         mcf_user_reg = 0, mcf_user_next;
179	
180	reg stat_rx_mcf_reg = 1'b0, stat_rx_mcf_next;
181	
182	assign s_axis_tready = s_axis_tready_reg;
183	
184	assign mcf_valid = mcf_valid_reg;
185	assign mcf_eth_dst = mcf_eth_dst_reg;
186	assign mcf_eth_src = mcf_eth_src_reg;
187	assign mcf_eth_type = mcf_eth_type_reg;
188	assign mcf_opcode = mcf_opcode_reg;
189	assign mcf_params = mcf_params_reg;
190	assign mcf_id = mcf_id_reg;
191	assign mcf_dest = mcf_dest_reg;
192	assign mcf_user = mcf_user_reg;
193	
194	assign stat_rx_mcf = stat_rx_mcf_reg;
195	
196	wire mcf_eth_dst_mcast_match = mcf_eth_dst_next == cfg_mcf_rx_eth_dst_mcast;
197	wire mcf_eth_dst_ucast_match = mcf_eth_dst_next == cfg_mcf_rx_eth_dst_ucast;
198	wire mcf_eth_src_match = mcf_eth_src_next == cfg_mcf_rx_eth_src;
199	wire mcf_eth_type_match = mcf_eth_type_next == cfg_mcf_rx_eth_type;
200	wire mcf_opcode_lfc_match = mcf_opcode_next == cfg_mcf_rx_opcode_lfc;
201	wire mcf_opcode_pfc_match = mcf_opcode_next == cfg_mcf_rx_opcode_pfc;
202	
203	wire mcf_eth_dst_match = ((mcf_eth_dst_mcast_match && cfg_mcf_rx_check_eth_dst_mcast) ||
204	    (mcf_eth_dst_ucast_match && cfg_mcf_rx_check_eth_dst_ucast) ||
205	    (!cfg_mcf_rx_check_eth_dst_mcast && !cfg_mcf_rx_check_eth_dst_ucast));
206	
207	wire mcf_opcode_match = ((mcf_opcode_lfc_match && cfg_mcf_rx_check_opcode_lfc) ||
208	    (mcf_opcode_pfc_match && cfg_mcf_rx_check_opcode_pfc) ||
209	    (!cfg_mcf_rx_check_opcode_lfc && !cfg_mcf_rx_check_opcode_pfc));
210	
211	wire mcf_match = (mcf_eth_dst_match &&
212	    (mcf_eth_src_match || !cfg_mcf_rx_check_eth_src) &&
213	    mcf_eth_type_match && mcf_opcode_match);
214	
215	integer k;
216	
217	always @* begin
218	    read_mcf_next = read_mcf_reg;
219	    mcf_frame_next = mcf_frame_reg;
220	    ptr_next = ptr_reg;
221	
222	    // pass through data
223	    m_axis_tdata_int = s_axis_tdata;
224	    m_axis_tkeep_int = s_axis_tkeep;
225	    m_axis_tvalid_int = s_axis_tvalid;
226	    m_axis_tlast_int = s_axis_tlast;
227	    m_axis_tid_int = s_axis_tid;
228	    m_axis_tdest_int = s_axis_tdest;
229	    m_axis_tuser_int = s_axis_tuser;
230	
231	    s_axis_tready_next = m_axis_tready_int_early || !USE_READY;
232	
233	    mcf_valid_next = 1'b0;
234	    mcf_eth_dst_next = mcf_eth_dst_reg;
235	    mcf_eth_src_next = mcf_eth_src_reg;
236	    mcf_eth_type_next = mcf_eth_type_reg;
237	    mcf_opcode_next = mcf_opcode_reg;
238	    mcf_params_next = mcf_params_reg;
239	    mcf_id_next = mcf_id_reg;
240	    mcf_dest_next = mcf_dest_reg;
241	    mcf_user_next = mcf_user_reg;
242	
243	    stat_rx_mcf_next = 1'b0;
244	
245	    if ((s_axis_tready || !USE_READY) && s_axis_tvalid) begin
246	        if (read_mcf_reg) begin
247	            ptr_next = ptr_reg + 1;
248	
249	            mcf_id_next = s_axis_tid;
250	            mcf_dest_next = s_axis_tdest;
251	            mcf_user_next = s_axis_tuser;
252	
253	            `define _HEADER_FIELD_(offset, field) \
254	                if (ptr_reg == offset/BYTE_LANES) begin \
255	                    field = s_axis_tdata[(offset%BYTE_LANES)*8 +: 8]; \
256	                end
257	
258	            `_HEADER_FIELD_(0,  mcf_eth_dst_next[5*8 +: 8])
259	            `_HEADER_FIELD_(1,  mcf_eth_dst_next[4*8 +: 8])
260	            `_HEADER_FIELD_(2,  mcf_eth_dst_next[3*8 +: 8])
261	            `_HEADER_FIELD_(3,  mcf_eth_dst_next[2*8 +: 8])
262	            `_HEADER_FIELD_(4,  mcf_eth_dst_next[1*8 +: 8])
263	            `_HEADER_FIELD_(5,  mcf_eth_dst_next[0*8 +: 8])
264	            `_HEADER_FIELD_(6,  mcf_eth_src_next[5*8 +: 8])
265	            `_HEADER_FIELD_(7,  mcf_eth_src_next[4*8 +: 8])
266	            `_HEADER_FIELD_(8,  mcf_eth_src_next[3*8 +: 8])
267	            `_HEADER_FIELD_(9,  mcf_eth_src_next[2*8 +: 8])
268	            `_HEADER_FIELD_(10, mcf_eth_src_next[1*8 +: 8])
269	            `_HEADER_FIELD_(11, mcf_eth_src_next[0*8 +: 8])
270	            `_HEADER_FIELD_(12, mcf_eth_type_next[1*8 +: 8])
271	            `_HEADER_FIELD_(13, mcf_eth_type_next[0*8 +: 8])
272	            `_HEADER_FIELD_(14, mcf_opcode_next[1*8 +: 8])
273	            `_HEADER_FIELD_(15, mcf_opcode_next[0*8 +: 8])
274	
275	            if (ptr_reg == 0/BYTE_LANES) begin
276	                // ensure params field gets cleared
277	                mcf_params_next = 0;
278	            end
279	
280	            for (k = 0; k < MCF_PARAMS_SIZE; k = k + 1) begin
281	                if (ptr_reg == (16+k)/BYTE_LANES) begin
282	                    mcf_params_next[k*8 +: 8] = s_axis_tdata[((16+k)%BYTE_LANES)*8 +: 8];
283	                end
284	            end
285	
286	            if (ptr_reg == 15/BYTE_LANES && (!KEEP_ENABLE || s_axis_tkeep[13%BYTE_LANES])) begin
287	                // record match at end of opcode field
288	                mcf_frame_next = mcf_match && cfg_mcf_rx_enable;
289	            end
290	
291	            if (ptr_reg == (HDR_SIZE-1)/BYTE_LANES) begin
292	                read_mcf_next = 1'b0;
293	            end
294	
295	            `undef _HEADER_FIELD_
296	        end
297	
298	        if (s_axis_tlast) begin
299	            if (s_axis_tuser[0]) begin
300	                // frame marked invalid
301	            end else if (mcf_frame_next) begin
302	                if (!cfg_mcf_rx_forward) begin
303	                    // mark frame invalid
304	                    m_axis_tuser_int[0] = 1'b1;
305	                end
306	                // transfer out MAC control frame
307	                mcf_valid_next = 1'b1;
308	                stat_rx_mcf_next = 1'b1;
309	            end
310	
311	            read_mcf_next = 1'b1;
312	            mcf_frame_next = 1'b0;
313	            ptr_next = 0;
314	        end
315	    end
316	end
317	
318	always @(posedge clk) begin
319	    read_mcf_reg <= read_mcf_next;
320	    mcf_frame_reg <= mcf_frame_next;
321	    ptr_reg <= ptr_next;
322	
323	    s_axis_tready_reg <= s_axis_tready_next;
324	
325	    mcf_valid_reg <= mcf_valid_next;
326	    mcf_eth_dst_reg <= mcf_eth_dst_next;
327	    mcf_eth_src_reg <= mcf_eth_src_next;
328	    mcf_eth_type_reg <= mcf_eth_type_next;
329	    mcf_opcode_reg <= mcf_opcode_next;
330	    mcf_params_reg <= mcf_params_next;
331	    mcf_id_reg <= mcf_id_next;
332	    mcf_dest_reg <= mcf_dest_next;
333	    mcf_user_reg <= mcf_user_next;
334	
335	    stat_rx_mcf_reg <= stat_rx_mcf_next;
336	
337	    if (rst) begin
338	        read_mcf_reg <= 1'b1;
339	        mcf_frame_reg <= 1'b0;
340	        ptr_reg <= 0;
341	        s_axis_tready_reg <= 1'b0;
342	        mcf_valid_reg <= 1'b0;
343	        stat_rx_mcf_reg <= 1'b0;
344	    end
345	end
346	
347	// output datapath logic
348	reg [DATA_WIDTH-1:0] m_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
349	reg [KEEP_WIDTH-1:0] m_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
350	reg                  m_axis_tvalid_reg = 1'b0, m_axis_tvalid_next;
351	reg                  m_axis_tlast_reg  = 1'b0;
352	reg [ID_WIDTH-1:0]   m_axis_tid_reg    = {ID_WIDTH{1'b0}};
353	reg [DEST_WIDTH-1:0] m_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
354	reg [USER_WIDTH-1:0] m_axis_tuser_reg  = {USER_WIDTH{1'b0}};
355	
356	reg [DATA_WIDTH-1:0] temp_m_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
357	reg [KEEP_WIDTH-1:0] temp_m_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
358	reg                  temp_m_axis_tvalid_reg = 1'b0, temp_m_axis_tvalid_next;
359	reg                  temp_m_axis_tlast_reg  = 1'b0;
360	reg [ID_WIDTH-1:0]   temp_m_axis_tid_reg    = {ID_WIDTH{1'b0}};
361	reg [DEST_WIDTH-1:0] temp_m_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
362	reg [USER_WIDTH-1:0] temp_m_axis_tuser_reg  = {USER_WIDTH{1'b0}};
363	
364	// datapath control
365	reg store_axis_int_to_output;
366	reg store_axis_int_to_temp;
367	reg store_axis_temp_to_output;
368	
369	assign m_axis_tdata  = m_axis_tdata_reg;
370	assign m_axis_tkeep  = KEEP_ENABLE ? m_axis_tkeep_reg : {KEEP_WIDTH{1'b1}};
371	assign m_axis_tvalid = m_axis_tvalid_reg;
372	assign m_axis_tlast  = m_axis_tlast_reg;
373	assign m_axis_tid    = ID_ENABLE   ? m_axis_tid_reg   : {ID_WIDTH{1'b0}};
374	assign m_axis_tdest  = DEST_ENABLE ? m_axis_tdest_reg : {DEST_WIDTH{1'b0}};
375	assign m_axis_tuser  = USER_ENABLE ? m_axis_tuser_reg : {USER_WIDTH{1'b0}};
376	
377	// enable ready input next cycle if output is ready or the temp reg will not be filled on the next cycle (output reg empty or no input)
378	assign m_axis_tready_int_early = m_axis_tready || !USE_READY || (!temp_m_axis_tvalid_reg && (!m_axis_tvalid_reg || !m_axis_tvalid_int));
379	
380	always @* begin
381	    // transfer sink ready state to source
382	    m_axis_tvalid_next = m_axis_tvalid_reg;
383	    temp_m_axis_tvalid_next = temp_m_axis_tvalid_reg;
384	
385	    store_axis_int_to_output = 1'b0;
386	    store_axis_int_to_temp = 1'b0;
387	    store_axis_temp_to_output = 1'b0;
388	
389	    if (m_axis_tready_int_reg) begin
390	        // input is ready
391	        if (m_axis_tready || !USE_READY || !m_axis_tvalid_reg) begin
392	            // output is ready or currently not valid, transfer data to output
393	            m_axis_tvalid_next = m_axis_tvalid_int;
394	            store_axis_int_to_output = 1'b1;
395	        end else begin
396	            // output is not ready, store input in temp
397	            temp_m_axis_tvalid_next = m_axis_tvalid_int;
398	            store_axis_int_to_temp = 1'b1;
399	        end
400	    end else if (m_axis_tready || !USE_READY) begin
401	        // input is not ready, but output is ready
402	        m_axis_tvalid_next = temp_m_axis_tvalid_reg;
403	        temp_m_axis_tvalid_next = 1'b0;
404	        store_axis_temp_to_output = 1'b1;
405	    end
406	end
407	
408	always @(posedge clk) begin
409	    m_axis_tvalid_reg <= m_axis_tvalid_next;
410	    m_axis_tready_int_reg <= m_axis_tready_int_early;
411	    temp_m_axis_tvalid_reg <= temp_m_axis_tvalid_next;
412	
413	    // datapath
414	    if (store_axis_int_to_output) begin
415	        m_axis_tdata_reg <= m_axis_tdata_int;
416	        m_axis_tkeep_reg <= m_axis_tkeep_int;
417	        m_axis_tlast_reg <= m_axis_tlast_int;
418	        m_axis_tid_reg   <= m_axis_tid_int;
419	        m_axis_tdest_reg <= m_axis_tdest_int;
420	        m_axis_tuser_reg <= m_axis_tuser_int;
421	    end else if (store_axis_temp_to_output) begin
422	        m_axis_tdata_reg <= temp_m_axis_tdata_reg;
423	        m_axis_tkeep_reg <= temp_m_axis_tkeep_reg;
424	        m_axis_tlast_reg <= temp_m_axis_tlast_reg;
425	        m_axis_tid_reg   <= temp_m_axis_tid_reg;
426	        m_axis_tdest_reg <= temp_m_axis_tdest_reg;
427	        m_axis_tuser_reg <= temp_m_axis_tuser_reg;
428	    end
429	
430	    if (store_axis_int_to_temp) begin
431	        temp_m_axis_tdata_reg <= m_axis_tdata_int;
432	        temp_m_axis_tkeep_reg <= m_axis_tkeep_int;
433	        temp_m_axis_tlast_reg <= m_axis_tlast_int;
434	        temp_m_axis_tid_reg   <= m_axis_tid_int;
435	        temp_m_axis_tdest_reg <= m_axis_tdest_int;
436	        temp_m_axis_tuser_reg <= m_axis_tuser_int;
437	    end
438	
439	    if (rst) begin
440	        m_axis_tvalid_reg <= 1'b0;
441	        m_axis_tready_int_reg <= 1'b0;
442	        temp_m_axis_tvalid_reg <= 1'b0;
443	    end
444	end
445	
446	endmodule
447	
448	`resetall
449

