33	 */
34	module mac_ctrl_tx #
35	(
36	    parameter DATA_WIDTH = 8,
37	    parameter KEEP_ENABLE = DATA_WIDTH>8,
38	    parameter KEEP_WIDTH = DATA_WIDTH/8,
39	    parameter ID_ENABLE = 0,
40	    parameter ID_WIDTH = 8,
41	    parameter DEST_ENABLE = 0,
42	    parameter DEST_WIDTH = 8,
43	    parameter USER_ENABLE = 1,
44	    parameter USER_WIDTH = 1,
45	    parameter MCF_PARAMS_SIZE = 18
46	)
47	(
48	    input  wire                          clk,
49	    input  wire                          rst,
50	
51	    /*
52	     * AXI stream input
53	     */
54	    input  wire [DATA_WIDTH-1:0]         s_axis_tdata,
55	    input  wire [KEEP_WIDTH-1:0]         s_axis_tkeep,
56	    input  wire                          s_axis_tvalid,
57	    output wire                          s_axis_tready,
58	    input  wire                          s_axis_tlast,
59	    input  wire [ID_WIDTH-1:0]           s_axis_tid,
60	    input  wire [DEST_WIDTH-1:0]         s_axis_tdest,
61	    input  wire [USER_WIDTH-1:0]         s_axis_tuser,
62	
63	    /*
64	     * AXI stream output
65	     */
66	    output wire [DATA_WIDTH-1:0]         m_axis_tdata,
67	    output wire [KEEP_WIDTH-1:0]         m_axis_tkeep,
68	    output wire                          m_axis_tvalid,
69	    input  wire                          m_axis_tready,
70	    output wire                          m_axis_tlast,
71	    output wire [ID_WIDTH-1:0]           m_axis_tid,
72	    output wire [DEST_WIDTH-1:0]         m_axis_tdest,
73	    output wire [USER_WIDTH-1:0]         m_axis_tuser,
74	
75	    /*
76	     * MAC control frame interface
77	     */
78	    input  wire                          mcf_valid,
79	    output wire                          mcf_ready,
80	    input  wire [47:0]                   mcf_eth_dst,
81	    input  wire [47:0]                   mcf_eth_src,
82	    input  wire [15:0]                   mcf_eth_type,
83	    input  wire [15:0]                   mcf_opcode,
84	    input  wire [MCF_PARAMS_SIZE*8-1:0]  mcf_params,
85	    input  wire [ID_WIDTH-1:0]           mcf_id,
86	    input  wire [DEST_WIDTH-1:0]         mcf_dest,
87	    input  wire [USER_WIDTH-1:0]         mcf_user,
88	
89	    /*
90	     * Pause interface
91	     */
92	    input  wire                          tx_pause_req,
93	    output wire                          tx_pause_ack,
94	
95	    /*
96	     * Status
97	     */
98	    output wire                          stat_tx_mcf
99	);
100	
101	parameter BYTE_LANES = KEEP_ENABLE ? KEEP_WIDTH : 1;
102	
103	parameter HDR_SIZE = 60;
104	
105	parameter CYCLE_COUNT = (HDR_SIZE+BYTE_LANES-1)/BYTE_LANES;
106	
107	parameter PTR_WIDTH = $clog2(CYCLE_COUNT);
108	
109	parameter OFFSET = HDR_SIZE % BYTE_LANES;
110	
111	// check configuration
112	initial begin
113	    if (BYTE_LANES * 8 != DATA_WIDTH) begin
114	        $error("Error: AXI stream interface requires byte (8-bit) granularity (instance %m)");
115	        $finish;
116	    end
117	
118	    if (MCF_PARAMS_SIZE > 44) begin
119	        $error("Error: Maximum MCF_PARAMS_SIZE is 44 bytes (instance %m)");
120	        $finish;
121	    end
122	end
123	
124	/*
125	
126	MAC control frame
127	
128	 Field                       Length
129	 Destination MAC address     6 octets [01:80:C2:00:00:01]
130	 Source MAC address          6 octets
131	 Ethertype                   2 octets [0x8808]
132	 Opcode                      2 octets
133	 Parameters                  0-44 octets
134	
135	This module manages the transmission of MAC control frames.  Control frames
136	are accepted in parallel, serialized, and merged at a higher priority with
137	data traffic.
138	
139	*/
140	
141	reg send_data_reg = 1'b0, send_data_next;
142	reg send_mcf_reg = 1'b0, send_mcf_next;
143	reg [PTR_WIDTH-1:0] ptr_reg = 0, ptr_next;
144	
145	reg s_axis_tready_reg = 1'b0, s_axis_tready_next;
146	reg mcf_ready_reg = 1'b0, mcf_ready_next;
147	reg tx_pause_ack_reg = 1'b0, tx_pause_ack_next;
148	reg stat_tx_mcf_reg = 1'b0, stat_tx_mcf_next;
149	
150	// internal datapath
151	reg  [DATA_WIDTH-1:0] m_axis_tdata_int;
152	reg  [KEEP_WIDTH-1:0] m_axis_tkeep_int;
153	reg                   m_axis_tvalid_int;
154	reg                   m_axis_tready_int_reg = 1'b0;
155	reg                   m_axis_tlast_int;
156	reg  [ID_WIDTH-1:0]   m_axis_tid_int;
157	reg  [DEST_WIDTH-1:0] m_axis_tdest_int;
158	reg  [USER_WIDTH-1:0] m_axis_tuser_int;
159	wire                  m_axis_tready_int_early;
160	
161	assign s_axis_tready = s_axis_tready_reg;
162	assign mcf_ready = mcf_ready_reg;
163	assign tx_pause_ack = tx_pause_ack_reg;
164	assign stat_tx_mcf = stat_tx_mcf_reg;
165	
166	integer k;
167	
168	always @* begin
169	    send_data_next = send_data_reg;
170	    send_mcf_next = send_mcf_reg;
171	    ptr_next = ptr_reg;
172	
173	    s_axis_tready_next = 1'b0;
174	    mcf_ready_next = 1'b0;
175	    tx_pause_ack_next = tx_pause_ack_reg;
176	    stat_tx_mcf_next = 1'b0;
177	
178	    m_axis_tdata_int = 0;
179	    m_axis_tkeep_int = 0;
180	    m_axis_tvalid_int = 1'b0;
181	    m_axis_tlast_int = 1'b0;
182	    m_axis_tid_int = 0;
183	    m_axis_tdest_int = 0;
184	    m_axis_tuser_int = 0;
185	
186	    if (!send_data_reg && !send_mcf_reg) begin
187	        m_axis_tdata_int = s_axis_tdata;
188	        m_axis_tkeep_int = s_axis_tkeep;
189	        m_axis_tvalid_int = 1'b0;
190	        m_axis_tlast_int = s_axis_tlast;
191	        m_axis_tid_int = s_axis_tid;
192	        m_axis_tdest_int = s_axis_tdest;
193	        m_axis_tuser_int = s_axis_tuser;
194	        s_axis_tready_next = m_axis_tready_int_early && !tx_pause_req;
195	        tx_pause_ack_next = tx_pause_req;
196	        if (s_axis_tvalid && s_axis_tready) begin
197	            s_axis_tready_next = m_axis_tready_int_early;
198	            tx_pause_ack_next = 1'b0;
199	            m_axis_tvalid_int = 1'b1;
200	            if (s_axis_tlast) begin
201	                s_axis_tready_next = m_axis_tready_int_early && !mcf_valid && !mcf_ready;
202	                send_data_next = 1'b0;
203	            end else begin
204	                send_data_next = 1'b1;
205	            end
206	        end else if (mcf_valid) begin
207	            s_axis_tready_next = 1'b0;
208	            ptr_next = 0;
209	            send_mcf_next = 1'b1;
210	            mcf_ready_next = (CYCLE_COUNT == 1) && m_axis_tready_int_early;
211	        end
212	    end
213	
214	    if (send_data_reg) begin
215	        m_axis_tdata_int = s_axis_tdata;
216	        m_axis_tkeep_int = s_axis_tkeep;
217	        m_axis_tvalid_int = 1'b0;
218	        m_axis_tlast_int = s_axis_tlast;
219	        m_axis_tid_int = s_axis_tid;
220	        m_axis_tdest_int = s_axis_tdest;
221	        m_axis_tuser_int = s_axis_tuser;
222	        s_axis_tready_next = m_axis_tready_int_early;
223	        if (s_axis_tvalid && s_axis_tready) begin
224	            m_axis_tvalid_int = 1'b1;
225	            if (s_axis_tlast) begin
226	                s_axis_tready_next = m_axis_tready_int_early && !tx_pause_req;
227	                send_data_next = 1'b0;
228	                if (mcf_valid) begin
229	                    s_axis_tready_next = 1'b0;
230	                    ptr_next = 0;
231	                    send_mcf_next = 1'b1;
232	                    mcf_ready_next = (CYCLE_COUNT == 1) && m_axis_tready_int_early;
233	                end
234	            end else begin
235	                send_data_next = 1'b1;
236	            end
237	        end
238	    end
239	
240	    if (send_mcf_reg) begin
241	        mcf_ready_next = (CYCLE_COUNT == 1 || ptr_reg == CYCLE_COUNT-1) && m_axis_tready_int_early;
242	        if (m_axis_tready_int_reg) begin
243	            ptr_next = ptr_reg + 1;
244	
245	            m_axis_tvalid_int = 1'b1;
246	            m_axis_tid_int = mcf_id;
247	            m_axis_tdest_int = mcf_dest;
248	            m_axis_tuser_int = mcf_user;
249	
250	            `define _HEADER_FIELD_(offset, field) \
251	                if (ptr_reg == offset/BYTE_LANES) begin \
252	                    m_axis_tdata_int[(offset%BYTE_LANES)*8 +: 8] = field; \
253	                    m_axis_tkeep_int[offset%BYTE_LANES] = 1'b1; \
254	                end
255	
256	            `_HEADER_FIELD_(0,  mcf_eth_dst[5*8 +: 8])
257	            `_HEADER_FIELD_(1,  mcf_eth_dst[4*8 +: 8])
258	            `_HEADER_FIELD_(2,  mcf_eth_dst[3*8 +: 8])
259	            `_HEADER_FIELD_(3,  mcf_eth_dst[2*8 +: 8])
260	            `_HEADER_FIELD_(4,  mcf_eth_dst[1*8 +: 8])
261	            `_HEADER_FIELD_(5,  mcf_eth_dst[0*8 +: 8])
262	            `_HEADER_FIELD_(6,  mcf_eth_src[5*8 +: 8])
263	            `_HEADER_FIELD_(7,  mcf_eth_src[4*8 +: 8])
264	            `_HEADER_FIELD_(8,  mcf_eth_src[3*8 +: 8])
265	            `_HEADER_FIELD_(9,  mcf_eth_src[2*8 +: 8])
266	            `_HEADER_FIELD_(10, mcf_eth_src[1*8 +: 8])
267	            `_HEADER_FIELD_(11, mcf_eth_src[0*8 +: 8])
268	            `_HEADER_FIELD_(12, mcf_eth_type[1*8 +: 8])
269	            `_HEADER_FIELD_(13, mcf_eth_type[0*8 +: 8])
270	            `_HEADER_FIELD_(14, mcf_opcode[1*8 +: 8])
271	            `_HEADER_FIELD_(15, mcf_opcode[0*8 +: 8])
272	
273	            for (k = 0; k < HDR_SIZE-16; k = k + 1) begin
274	                if (ptr_reg == (16+k)/BYTE_LANES) begin
275	                    if (k < MCF_PARAMS_SIZE) begin
276	                        m_axis_tdata_int[((16+k)%BYTE_LANES)*8 +: 8] = mcf_params[k*8 +: 8];
277	                    end else begin
278	                        m_axis_tdata_int[((16+k)%BYTE_LANES)*8 +: 8] = 0;
279	                    end
280	                    m_axis_tkeep_int[(16+k)%BYTE_LANES] = 1'b1;
281	                end
282	            end
283	
284	            if (ptr_reg == (HDR_SIZE-1)/BYTE_LANES) begin
285	                s_axis_tready_next = m_axis_tready_int_early && !tx_pause_req;
286	                mcf_ready_next = 1'b0;
287	                m_axis_tlast_int = 1'b1;
288	                send_mcf_next = 1'b0;
289	                stat_tx_mcf_next = 1'b1;
290	            end else begin
291	                mcf_ready_next = (ptr_next == CYCLE_COUNT-1) && m_axis_tready_int_early;
292	            end
293	
294	            `undef _HEADER_FIELD_
295	        end
296	    end
297	end
298	
299	always @(posedge clk) begin
300	    send_data_reg <= send_data_next;
301	    send_mcf_reg <= send_mcf_next;
302	    ptr_reg <= ptr_next;
303	
304	    s_axis_tready_reg <= s_axis_tready_next;
305	    mcf_ready_reg <= mcf_ready_next;
306	    tx_pause_ack_reg <= tx_pause_ack_next;
307	    stat_tx_mcf_reg <= stat_tx_mcf_next;
308	
309	    if (rst) begin
310	        send_data_reg <= 1'b0;
311	        send_mcf_reg <= 1'b0;
312	        ptr_reg <= 0;
313	        s_axis_tready_reg <= 1'b0;
314	        mcf_ready_reg <= 1'b0;
315	        tx_pause_ack_reg <= 1'b0;
316	        stat_tx_mcf_reg <= 1'b0;
317	    end
318	end
319	
320	// output datapath logic
321	reg [DATA_WIDTH-1:0] m_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
322	reg [KEEP_WIDTH-1:0] m_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
323	reg                  m_axis_tvalid_reg = 1'b0, m_axis_tvalid_next;
324	reg                  m_axis_tlast_reg  = 1'b0;
325	reg [ID_WIDTH-1:0]   m_axis_tid_reg    = {ID_WIDTH{1'b0}};
326	reg [DEST_WIDTH-1:0] m_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
327	reg [USER_WIDTH-1:0] m_axis_tuser_reg  = {USER_WIDTH{1'b0}};
328	
329	reg [DATA_WIDTH-1:0] temp_m_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
330	reg [KEEP_WIDTH-1:0] temp_m_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
331	reg                  temp_m_axis_tvalid_reg = 1'b0, temp_m_axis_tvalid_next;
332	reg                  temp_m_axis_tlast_reg  = 1'b0;
333	reg [ID_WIDTH-1:0]   temp_m_axis_tid_reg    = {ID_WIDTH{1'b0}};
334	reg [DEST_WIDTH-1:0] temp_m_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
335	reg [USER_WIDTH-1:0] temp_m_axis_tuser_reg  = {USER_WIDTH{1'b0}};
336	
337	// datapath control
338	reg store_axis_int_to_output;
339	reg store_axis_int_to_temp;
340	reg store_axis_temp_to_output;
341	
342	assign m_axis_tdata  = m_axis_tdata_reg;
343	assign m_axis_tkeep  = KEEP_ENABLE ? m_axis_tkeep_reg : {KEEP_WIDTH{1'b1}};
344	assign m_axis_tvalid = m_axis_tvalid_reg;
345	assign m_axis_tlast  = m_axis_tlast_reg;
346	assign m_axis_tid    = ID_ENABLE   ? m_axis_tid_reg   : {ID_WIDTH{1'b0}};
347	assign m_axis_tdest  = DEST_ENABLE ? m_axis_tdest_reg : {DEST_WIDTH{1'b0}};
348	assign m_axis_tuser  = USER_ENABLE ? m_axis_tuser_reg : {USER_WIDTH{1'b0}};
349	
350	// enable ready input next cycle if output is ready or the temp reg will not be filled on the next cycle (output reg empty or no input)
351	assign m_axis_tready_int_early = m_axis_tready || (!temp_m_axis_tvalid_reg && (!m_axis_tvalid_reg || !m_axis_tvalid_int));
352	
353	always @* begin
354	    // transfer sink ready state to source
355	    m_axis_tvalid_next = m_axis_tvalid_reg;
356	    temp_m_axis_tvalid_next = temp_m_axis_tvalid_reg;
357	
358	    store_axis_int_to_output = 1'b0;
359	    store_axis_int_to_temp = 1'b0;
360	    store_axis_temp_to_output = 1'b0;
361	
362	    if (m_axis_tready_int_reg) begin
363	        // input is ready
364	        if (m_axis_tready || !m_axis_tvalid_reg) begin
365	            // output is ready or currently not valid, transfer data to output
366	            m_axis_tvalid_next = m_axis_tvalid_int;
367	            store_axis_int_to_output = 1'b1;
368	        end else begin
369	            // output is not ready, store input in temp
370	            temp_m_axis_tvalid_next = m_axis_tvalid_int;
371	            store_axis_int_to_temp = 1'b1;
372	        end
373	    end else if (m_axis_tready) begin
374	        // input is not ready, but output is ready
375	        m_axis_tvalid_next = temp_m_axis_tvalid_reg;
376	        temp_m_axis_tvalid_next = 1'b0;
377	        store_axis_temp_to_output = 1'b1;
378	    end
379	end
380	
381	always @(posedge clk) begin
382	    m_axis_tvalid_reg <= m_axis_tvalid_next;
383	    m_axis_tready_int_reg <= m_axis_tready_int_early;
384	    temp_m_axis_tvalid_reg <= temp_m_axis_tvalid_next;
385	
386	    // datapath
387	    if (store_axis_int_to_output) begin
388	        m_axis_tdata_reg <= m_axis_tdata_int;
389	        m_axis_tkeep_reg <= m_axis_tkeep_int;
390	        m_axis_tlast_reg <= m_axis_tlast_int;
391	        m_axis_tid_reg   <= m_axis_tid_int;
392	        m_axis_tdest_reg <= m_axis_tdest_int;
393	        m_axis_tuser_reg <= m_axis_tuser_int;
394	    end else if (store_axis_temp_to_output) begin
395	        m_axis_tdata_reg <= temp_m_axis_tdata_reg;
396	        m_axis_tkeep_reg <= temp_m_axis_tkeep_reg;
397	        m_axis_tlast_reg <= temp_m_axis_tlast_reg;
398	        m_axis_tid_reg   <= temp_m_axis_tid_reg;
399	        m_axis_tdest_reg <= temp_m_axis_tdest_reg;
400	        m_axis_tuser_reg <= temp_m_axis_tuser_reg;
401	    end
402	
403	    if (store_axis_int_to_temp) begin
404	        temp_m_axis_tdata_reg <= m_axis_tdata_int;
405	        temp_m_axis_tkeep_reg <= m_axis_tkeep_int;
406	        temp_m_axis_tlast_reg <= m_axis_tlast_int;
407	        temp_m_axis_tid_reg   <= m_axis_tid_int;
408	        temp_m_axis_tdest_reg <= m_axis_tdest_int;
409	        temp_m_axis_tuser_reg <= m_axis_tuser_int;
410	    end
411	
412	    if (rst) begin
413	        m_axis_tvalid_reg <= 1'b0;
414	        m_axis_tready_int_reg <= 1'b0;
415	        temp_m_axis_tvalid_reg <= 1'b0;
416	    end
417	end
418	
419	endmodule
420	
421	`resetall
422

