45	     */
46	    output wire                          mcf_valid,
47	    input  wire                          mcf_ready,
48	    output wire [47:0]                   mcf_eth_dst,
49	    output wire [47:0]                   mcf_eth_src,
50	    output wire [15:0]                   mcf_eth_type,
51	    output wire [15:0]                   mcf_opcode,
52	    output wire [MCF_PARAMS_SIZE*8-1:0]  mcf_params,
53	
54	    /*
55	     * Link-level Flow Control (LFC) (IEEE 802.3 annex 31B PAUSE)
56	     */
57	    input  wire                          tx_lfc_req,
58	    input  wire                          tx_lfc_resend,
59	
60	    /*
61	     * Priority Flow Control (PFC) (IEEE 802.3 annex 31D)
62	     */
63	    input  wire [7:0]                    tx_pfc_req,
64	    input  wire                          tx_pfc_resend,
65	
66	    /*
67	     * Configuration
68	     */
69	    input  wire [47:0]                   cfg_tx_lfc_eth_dst,
70	    input  wire [47:0]                   cfg_tx_lfc_eth_src,
71	    input  wire [15:0]                   cfg_tx_lfc_eth_type,
72	    input  wire [15:0]                   cfg_tx_lfc_opcode,
73	    input  wire                          cfg_tx_lfc_en,
74	    input  wire [15:0]                   cfg_tx_lfc_quanta,
75	    input  wire [15:0]                   cfg_tx_lfc_refresh,
76	    input  wire [47:0]                   cfg_tx_pfc_eth_dst,
77	    input  wire [47:0]                   cfg_tx_pfc_eth_src,
78	    input  wire [15:0]                   cfg_tx_pfc_eth_type,
79	    input  wire [15:0]                   cfg_tx_pfc_opcode,
80	    input  wire                          cfg_tx_pfc_en,
81	    input  wire [8*16-1:0]               cfg_tx_pfc_quanta,
82	    input  wire [8*16-1:0]               cfg_tx_pfc_refresh,
83	    input  wire [9:0]                    cfg_quanta_step,
84	    input  wire                          cfg_quanta_clk_en,
85	
86	    /*
87	     * Status
88	     */
89	    output wire                          stat_tx_lfc_pkt,
90	    output wire                          stat_tx_lfc_xon,
91	    output wire                          stat_tx_lfc_xoff,
92	    output wire                          stat_tx_lfc_paused,
93	    output wire                          stat_tx_pfc_pkt,
94	    output wire [7:0]                    stat_tx_pfc_xon,
95	    output wire [7:0]                    stat_tx_pfc_xoff,
96	    output wire [7:0]                    stat_tx_pfc_paused
97	);
98	
99	localparam QFB = 8;
100	
101	// check configuration
102	initial begin
103	    if (MCF_PARAMS_SIZE < (PFC_ENABLE ? 18 : 2)) begin
104	        $error("Error: MCF_PARAMS_SIZE too small for requested configuration (instance %m)");
105	        $finish;
106	    end
107	end
108	
109	reg lfc_req_reg = 1'b0, lfc_req_next;
110	reg lfc_act_reg = 1'b0, lfc_act_next;
111	reg lfc_send_reg = 1'b0, lfc_send_next;
112	reg [7:0] pfc_req_reg = 8'd0, pfc_req_next;
113	reg [7:0] pfc_act_reg = 8'd0, pfc_act_next;
114	reg [7:0] pfc_en_reg = 8'd0, pfc_en_next;
115	reg pfc_send_reg = 1'b0, pfc_send_next;
116	
117	reg [16+QFB-1:0] lfc_refresh_reg = 0, lfc_refresh_next;
118	reg [16+QFB-1:0] pfc_refresh_reg[0:7], pfc_refresh_next[0:7];
119	
120	reg stat_tx_lfc_pkt_reg = 1'b0, stat_tx_lfc_pkt_next;
121	reg stat_tx_lfc_xon_reg = 1'b0, stat_tx_lfc_xon_next;
122	reg stat_tx_lfc_xoff_reg = 1'b0, stat_tx_lfc_xoff_next;
123	reg stat_tx_pfc_pkt_reg = 1'b0, stat_tx_pfc_pkt_next;
124	reg [7:0] stat_tx_pfc_xon_reg = 0, stat_tx_pfc_xon_next;
125	reg [7:0] stat_tx_pfc_xoff_reg = 0, stat_tx_pfc_xoff_next;
126	
127	// MAC control interface
128	reg             mcf_pfc_sel_reg = PFC_ENABLE != 0, mcf_pfc_sel_next;
129	reg             mcf_valid_reg = 1'b0, mcf_valid_next;
130	
131	wire [2*8-1:0] mcf_lfc_params;
132	assign mcf_lfc_params[16*0 +: 16] = lfc_req_reg ? {cfg_tx_lfc_quanta[0 +: 8], cfg_tx_lfc_quanta[8 +: 8]} : 0;
133	
134	wire [18*8-1:0] mcf_pfc_params;
135	assign mcf_pfc_params[16*0 +: 16] = {pfc_en_reg, 8'd0};
136	assign mcf_pfc_params[16*1 +: 16] = pfc_req_reg[0] ? {cfg_tx_pfc_quanta[16*0+0 +: 8], cfg_tx_pfc_quanta[16*0+8 +: 8]} : 0;
137	assign mcf_pfc_params[16*2 +: 16] = pfc_req_reg[1] ? {cfg_tx_pfc_quanta[16*1+0 +: 8], cfg_tx_pfc_quanta[16*1+8 +: 8]} : 0;
138	assign mcf_pfc_params[16*3 +: 16] = pfc_req_reg[2] ? {cfg_tx_pfc_quanta[16*2+0 +: 8], cfg_tx_pfc_quanta[16*2+8 +: 8]} : 0;
139	assign mcf_pfc_params[16*4 +: 16] = pfc_req_reg[3] ? {cfg_tx_pfc_quanta[16*3+0 +: 8], cfg_tx_pfc_quanta[16*3+8 +: 8]} : 0;
140	assign mcf_pfc_params[16*5 +: 16] = pfc_req_reg[4] ? {cfg_tx_pfc_quanta[16*4+0 +: 8], cfg_tx_pfc_quanta[16*4+8 +: 8]} : 0;
141	assign mcf_pfc_params[16*6 +: 16] = pfc_req_reg[5] ? {cfg_tx_pfc_quanta[16*5+0 +: 8], cfg_tx_pfc_quanta[16*5+8 +: 8]} : 0;
142	assign mcf_pfc_params[16*7 +: 16] = pfc_req_reg[6] ? {cfg_tx_pfc_quanta[16*6+0 +: 8], cfg_tx_pfc_quanta[16*6+8 +: 8]} : 0;
143	assign mcf_pfc_params[16*8 +: 16] = pfc_req_reg[7] ? {cfg_tx_pfc_quanta[16*7+0 +: 8], cfg_tx_pfc_quanta[16*7+8 +: 8]} : 0;
144	
145	assign mcf_valid = mcf_valid_reg;
146	assign mcf_eth_dst  = (PFC_ENABLE && mcf_pfc_sel_reg) ? cfg_tx_pfc_eth_dst  : cfg_tx_lfc_eth_dst;
147	assign mcf_eth_src  = (PFC_ENABLE && mcf_pfc_sel_reg) ? cfg_tx_pfc_eth_src  : cfg_tx_lfc_eth_src;
148	assign mcf_eth_type = (PFC_ENABLE && mcf_pfc_sel_reg) ? cfg_tx_pfc_eth_type : cfg_tx_lfc_eth_type;
149	assign mcf_opcode   = (PFC_ENABLE && mcf_pfc_sel_reg) ? cfg_tx_pfc_opcode   : cfg_tx_lfc_opcode;
150	assign mcf_params   = (PFC_ENABLE && mcf_pfc_sel_reg) ? mcf_pfc_params      : mcf_lfc_params;
151	
152	assign stat_tx_lfc_pkt = stat_tx_lfc_pkt_reg;
153	assign stat_tx_lfc_xon = stat_tx_lfc_xon_reg;
154	assign stat_tx_lfc_xoff = stat_tx_lfc_xoff_reg;
155	assign stat_tx_lfc_paused = lfc_req_reg;
156	assign stat_tx_pfc_pkt = stat_tx_pfc_pkt_reg;
157	assign stat_tx_pfc_xon = stat_tx_pfc_xon_reg;
158	assign stat_tx_pfc_xoff = stat_tx_pfc_xoff_reg;
159	assign stat_tx_pfc_paused = pfc_req_reg;
160	
161	integer k;
162	
163	initial begin
164	    for (k = 0; k < 8; k = k + 1) begin
165	        pfc_refresh_reg[k] = 0;
166	    end
167	end
168	
169	always @* begin
170	    lfc_req_next = lfc_req_reg;
171	    lfc_act_next = lfc_act_reg;
172	    lfc_send_next = lfc_send_reg | tx_lfc_resend;
173	    pfc_req_next = pfc_req_reg;
174	    pfc_act_next = pfc_act_reg;
175	    pfc_en_next = pfc_en_reg;
176	    pfc_send_next = pfc_send_reg | tx_pfc_resend;
177	
178	    mcf_pfc_sel_next = mcf_pfc_sel_reg;
179	    mcf_valid_next = mcf_valid_reg && !mcf_ready;
180	
181	    stat_tx_lfc_pkt_next = 1'b0;
182	    stat_tx_lfc_xon_next = 1'b0;
183	    stat_tx_lfc_xoff_next = 1'b0;
184	    stat_tx_pfc_pkt_next = 1'b0;
185	    stat_tx_pfc_xon_next = 0;
186	    stat_tx_pfc_xoff_next = 0;
187	
188	    if (cfg_quanta_clk_en) begin
189	        if (lfc_refresh_reg > cfg_quanta_step) begin
190	            lfc_refresh_next = lfc_refresh_reg - cfg_quanta_step;
191	        end else begin
192	            lfc_refresh_next = 0;
193	            if (lfc_req_reg) begin
194	                lfc_send_next = 1'b1;
195	            end
196	        end
197	    end else begin
198	        lfc_refresh_next = lfc_refresh_reg;
199	    end
200	
201	    for (k = 0; k < 8; k = k + 1) begin
202	        if (cfg_quanta_clk_en) begin
203	            if (pfc_refresh_reg[k] > cfg_quanta_step) begin
204	                pfc_refresh_next[k] = pfc_refresh_reg[k] - cfg_quanta_step;
205	            end else begin
206	                pfc_refresh_next[k] = 0;
207	                if (pfc_req_reg[k]) begin
208	                    pfc_send_next = 1'b1;
209	                end
210	            end
211	        end else begin
212	            pfc_refresh_next[k] = pfc_refresh_reg[k];
213	        end
214	    end
215	
216	    if (cfg_tx_lfc_en) begin
217	        if (!mcf_valid_reg) begin
218	            if (lfc_req_reg != tx_lfc_req) begin
219	                lfc_req_next = tx_lfc_req;
220	                lfc_act_next = lfc_act_reg | tx_lfc_req;
221	                lfc_send_next = 1'b1;
222	            end
223	
224	            if (lfc_send_reg && !(PFC_ENABLE && cfg_tx_pfc_en && pfc_send_reg)) begin
225	                mcf_pfc_sel_next = 1'b0;
226	                mcf_valid_next = lfc_act_reg;
227	                lfc_act_next = lfc_req_reg;
228	                lfc_refresh_next = lfc_req_reg ? {cfg_tx_lfc_refresh, {QFB{1'b0}}} : 0;
229	                lfc_send_next = 1'b0;
230	
231	                stat_tx_lfc_pkt_next = lfc_act_reg;
232	                stat_tx_lfc_xon_next = lfc_act_reg && !lfc_req_reg;
233	                stat_tx_lfc_xoff_next = lfc_act_reg && lfc_req_reg;
234	            end
235	        end
236	    end
237	
238	    if (PFC_ENABLE && cfg_tx_pfc_en) begin
239	        if (!mcf_valid_reg) begin
240	            if (pfc_req_reg != tx_pfc_req) begin
241	                pfc_req_next = tx_pfc_req;
242	                pfc_act_next = pfc_act_reg | tx_pfc_req;
243	                pfc_send_next = 1'b1;
244	            end
245	
246	            if (pfc_send_reg) begin
247	                mcf_pfc_sel_next = 1'b1;
248	                mcf_valid_next = pfc_act_reg != 0;
249	                pfc_en_next = pfc_act_reg;
250	                pfc_act_next = pfc_req_reg;
251	                for (k = 0; k < 8; k = k + 1) begin
252	                    pfc_refresh_next[k] = pfc_req_reg[k] ? {cfg_tx_pfc_refresh[16*k +: 16], {QFB{1'b0}}} : 0;
253	                end
254	                pfc_send_next = 1'b0;
255	
256	                stat_tx_pfc_pkt_next = pfc_act_reg != 0;
257	                stat_tx_pfc_xon_next = pfc_act_reg & ~pfc_req_reg;
258	                stat_tx_pfc_xoff_next = pfc_act_reg & pfc_req_reg;
259	            end
260	        end
261	    end
262	end
263	
264	always @(posedge clk) begin
265	    lfc_req_reg <= lfc_req_next;
266	    lfc_act_reg <= lfc_act_next;
267	    lfc_send_reg <= lfc_send_next;
268	    pfc_req_reg <= pfc_req_next;
269	    pfc_act_reg <= pfc_act_next;
270	    pfc_en_reg <= pfc_en_next;
271	    pfc_send_reg <= pfc_send_next;
272	
273	    mcf_pfc_sel_reg <= mcf_pfc_sel_next;
274	    mcf_valid_reg <= mcf_valid_next;
275	
276	    lfc_refresh_reg <= lfc_refresh_next;
277	    for (k = 0; k < 8; k = k + 1) begin
278	        pfc_refresh_reg[k] <= pfc_refresh_next[k];
279	    end
280	
281	    stat_tx_lfc_pkt_reg <= stat_tx_lfc_pkt_next;
282	    stat_tx_lfc_xon_reg <= stat_tx_lfc_xon_next;
283	    stat_tx_lfc_xoff_reg <= stat_tx_lfc_xoff_next;
284	    stat_tx_pfc_pkt_reg <= stat_tx_pfc_pkt_next;
285	    stat_tx_pfc_xon_reg <= stat_tx_pfc_xon_next;
286	    stat_tx_pfc_xoff_reg <= stat_tx_pfc_xoff_next;
287	
288	    if (rst) begin
289	        lfc_req_reg <= 1'b0;
290	        lfc_act_reg <= 1'b0;
291	        lfc_send_reg <= 1'b0;
292	        pfc_req_reg <= 0;
293	        pfc_act_reg <= 0;
294	        pfc_send_reg <= 0;
295	        mcf_pfc_sel_reg <= PFC_ENABLE != 0;
296	        mcf_valid_reg <= 1'b0;
297	        lfc_refresh_reg <= 0;
298	        for (k = 0; k < 8; k = k + 1) begin
299	            pfc_refresh_reg[k] <= 0;
300	        end
301	
302	        stat_tx_lfc_pkt_reg <= 1'b0;
303	        stat_tx_lfc_xon_reg <= 1'b0;
304	        stat_tx_lfc_xoff_reg <= 1'b0;
305	        stat_tx_pfc_pkt_reg <= 1'b0;
306	        stat_tx_pfc_xon_reg <= 0;
307	        stat_tx_pfc_xoff_reg <= 0;
308	    end
309	end
310	
311	endmodule
